 1	/*                                      Functional Lists and Imperative Arrays                                        */
 2	
 3	/*
 4	    Daniel Cavalheiro   57869
 5	    Pedro Nunes        57854
 6	*/
 7	
 8	datatype List<T> = Nil | Cons(head: T, tail: List<T>)
 9	
10	function length<T>(l: List<T>): nat
11	{
12	  match l
13	  case Nil => 0
14	  case Cons(_, t) => 1 + length(t)
15	}
16	
17	predicate mem<T(==)> (l: List<T>, x: T)
18	{
19	  match l
20	  case Nil => false
21	  case Cons(h, t) => if(h == x) then true else mem(t, x)
22	}
23	
24	function at<T>(l: List<T>, i: nat): T
25	  requires i < (length(l) + 1)
26	{
27	  if i == 0 then l.head else at(l.tail, i - 1)
28	}
29	
30	method from_array<T>(a: array<T>) returns (l: List<T>)
31	  requires a.Length >= 0
32	  ensures length(l) == a.Length
33	  ensures forall i: int :: 0 <= i < length(l) ==> at(l, i) == a[i]
34	  ensures forall x :: mem(l, x) ==> exists i: int :: 0 <= i < length(l) && a[i] == x
35	{
36	  l := Nil;
37	  var i: int := a.Length - 1;
38	  while(i >= 0)
39	    invariant -1 <= i <= a.Length - 1
40	    invariant length(l) == a.Length - 1 - i
41	    invariant forall j: int :: i < j < a.Length ==> at(l,j-i-1) == a[j]
42	    invariant forall x :: mem(l, x) ==> exists k: int :: i < k < a.Length && a[k] == x
43	  {
44	    l := Cons(a[i], l);
45	    i := i-1;
46	  }
47	}
48	
49	method Main() {
50	  var l: List<int> := List.Cons(1, List.Cons(2, List.Cons(3, Nil)));
51	  var arr: array<int> := new int [3](i => i + 1);
52	  var t: List<int> := from_array(arr);
53	  print l;
54	  print "\n";
55	  print t;
56	  print "\n";
57	  print t == l;
58	}

